/// `String.CASE_INSENSITIVE_ORDER`: compares char by char after `toUpperCase` then `toLowerCase`.
pub(crate) fn case_insensitive_order(a: &str, b: &str) -> std::cmp::Ordering {
    fn fold(c: char) -> char {
        let u = c.to_uppercase().next().unwrap_or(c);
        u.to_lowercase().next().unwrap_or(u)
    }
    let mut ai = a.encode_utf16();
    let mut bi = b.encode_utf16();
    loop {
        match (ai.next(), bi.next()) {
            (None, None) => return std::cmp::Ordering::Equal,
            (None, Some(_)) => return std::cmp::Ordering::Less,
            (Some(_), None) => return std::cmp::Ordering::Greater,
            (Some(x), Some(y)) => {
                if x != y {
                    let cx = char::from_u32(x as u32)
                        .map(fold)
                        .map(|c| c as u32)
                        .unwrap_or(x as u32);
                    let cy = char::from_u32(y as u32)
                        .map(fold)
                        .map(|c| c as u32)
                        .unwrap_or(y as u32);
                    if cx != cy {
                        return cx.cmp(&cy);
                    }
                }
            }
        }
    }
}

